/*
 * A063792  Subtractive primes: p = x1x2x3..xk is a k-digit prime in base 10
 *          such that abs(x1-x2-x3-...-xk) is also a prime.
 * https://oeis.org/A063792
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, base
 * Formula:   a(n) is the n-th prime p such that * |(most significant digit of
 *            p) – (sum of the remaining digits)| * is also a prime (greater
 *            than 1). The sequence is generated by * sieving primes up to a
 *            fixed limit and filtering those that satisfy * the stated
 *            property
 * Range:     u8 n <= 25, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

/* Small primality test, sufficient for the small difference values
 * that arise (at most 9 * number_of_digits(p)). */
static bool is_prime_small(uint64_t n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (uint64_t d = 3; d * d <= n; d += 2)
        if (n % d == 0) return false;
    return true;
}

/* Test whether a prime p satisfies the subtractive condition. */
static bool is_subprime(uint64_t p) {
    uint8_t digits[20];
    size_t dlen = 0;
    uint64_t tmp = p;
    while (tmp > 0) {
        digits[dlen++] = (uint8_t)(tmp % 10);
        tmp /= 10;
    }
    if (dlen == 0) return false;              /* shouldn't happen for primes */
    uint64_t sum_rest = 0;
    for (size_t i = 0; i + 1 < dlen; ++i)
        sum_rest += digits[i];
    uint64_t most = digits[dlen - 1];
    uint64_t diff = most > sum_rest ? most - sum_rest : sum_rest - most;
    if (diff <= 1) return false;              /* 0 or 1 are not prime */
    return is_prime_small(diff);
}

/* Global storage for the sequence. */
static seq_t *subprimes = NULL;
static size_t subprime_len = 0;
static size_t subprime_cap = 0;
static bool initialized = false;

/* Helper to grow the sequence array. */
static void grow_subprimes(void) {
    if (subprime_cap == 0) {
        subprime_cap = 1024;
        subprimes = (seq_t *)malloc(subprime_cap * sizeof(seq_t));
    } else {
        subprime_cap <<= 1;
        subprimes = (seq_t *)realloc(subprimes, subprime_cap * sizeof(seq_t));
    }
}

/* Generate primes up to LIMIT via a simple sieve and filter them. */
static void init_primes(void) {
    const idx_t LIMIT = 10000000;  /* 10^7 is ample for n ≤ 10 000 */
    bool *sieve = (bool *)malloc((LIMIT + 1) * sizeof(bool));
    for (idx_t i = 2; i <= LIMIT; ++i) sieve[i] = true;

    for (idx_t p = 2; p * p <= LIMIT; ++p) {
        if (sieve[p]) {
            for (idx_t m = p * p; m <= LIMIT; m += p)
                sieve[m] = false;
        }
    }

    for (idx_t cand = 2; cand <= LIMIT; ++cand) {
        if (!sieve[cand]) continue;
        if (is_subprime((uint64_t)cand)) {
            if (subprime_len == subprime_cap) grow_subprimes();
            subprimes[subprime_len++] = (seq_t)cand;
        }
    }
    free(sieve);
    initialized = true;
}

seq_t a(idx_t n) {
    if (n == 0) return 0;          /* undefined for offset 1, return 0 as safe sentinel */
    if (!initialized) init_primes();
    if ((idx_t)n > subprime_len) return 0;
    return subprimes[n - 1];
}
